// =============================================================================
//  LocalizationHIN.cpp -- Hindi (Devanagari) overlay tables.   (th4)
//
//  READ vars.h FIRST. Hindi is the opposite of Arabic in the one way that matters:
//  the bytes in these tables are VISUAL and PRE-SHAPED, not logical.
//
//  Devanagari needs three things the engine cannot do at draw time without new
//  logic at every text site: consonant clusters fuse into half-form + base, the
//  short-i matra is stored after its consonant but drawn BEFORE it, and vowel signs
//  stack above and below with zero advance. Rather than add a cluster segmenter, a
//  reorder pass and per-glyph offsets, the BUILD resolves all three offline with a
//  real shaper and stores each cluster as one pre-composed cell in visual order.
//  ChiLetterID then maps a byte pair straight to that cell, exactly as it does for
//  Japanese, and every existing draw site works untouched.
//
//  WHAT THAT COSTS: cell count. "ka" is one cell, but ki, ku, kuu, ke, kai, ko, kau
//  and every conjunct are each their own image -- about 1200 cells over 20 lead rows
//  instead of Arabic's 188 over two. Only clusters that actually occur in the text
//  are generated, so this file and TH4loc_hin.mor must ALWAYS be rebuilt together:
//  a pair here that the pack has no cell for draws nothing.
//
//  ENCODING: lead 0xA1..0xB4, trail 0xA1..0xFE. Both bytes >= 0xA1 so a trail can
//  never be mistaken for a colour-control code, the same reason Arabic and Japanese
//  use private encodings rather than UTF-8.
//
//  EMPTY IS VALID. Every table below starts empty and each missing id falls back to
//  English, so this compiles and runs as an all-English "Hindi" build while the
//  translation is being written.
// =============================================================================

#include "stdafx.h"

// Every localization unit declares its OWN pair of these -- they are file-local,
// not shared through a header, so this file needs its own copy. The second
// column is named .hin here for the same reason AR calls it .ar: it documents
// which language the row belongs to when you are reading the table.
struct UiStr  { const char* en; const char* hin; };
struct IdxStr { int index; const char* hin; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_WARP_OBL,
	OVL_STR_COUNT
};

enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// (th4) A lone { 0, 0 } row counts as 0 so an unfilled table falls back to English,
// while a genuine 1-row table still counts. The overloaded isPlaceholder() is what
// makes one template serve BOTH row types -- an earlier version reached for t[0].en,
// which IdxStr does not have, and only broke once a table grew past one row. Same
// shape BG, UK and JA use; do not "simplify" it back.
static bool isPlaceholder( const UiStr& r )  { return r.en == 0 && r.hin == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index == 0 && r.hin == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

