const UiStr* HIN_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(HIN_Ui);           return HIN_Ui;
		case OVL_MENU:          *n = countRows(HIN_Menu);         return HIN_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(HIN_UniqueItem);   return HIN_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(HIN_AffixPrefix);  return HIN_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(HIN_AffixSuffix);  return HIN_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(HIN_BaseItem);     return HIN_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(HIN_BaseName2);    return HIN_BaseName2;
		case OVL_ELEMENT:       *n = countRows(HIN_Element);      return HIN_Element;
		case OVL_SPICIES:       *n = countRows(HIN_Spicies);      return HIN_Spicies;
		case OVL_ICEAGE:        *n = countRows(HIN_IceAge);       return HIN_IceAge;
		case OVL_SPELL:         *n = countRows(HIN_Spell);        return HIN_Spell;
		case OVL_SPELL_NOM:     *n = countRows(HIN_SpellNom);     return HIN_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(HIN_PerkName);     return HIN_PerkName;
		case OVL_PERK_DESC:     *n = countRows(HIN_PerkDesc);     return HIN_PerkDesc;
		case OVL_WARP:          *n = countRows(HIN_Warp);         return HIN_Warp;
		case OVL_WARP_OBL:      *n = countRows(HIN_WarpOblique);  return HIN_WarpOblique;
	}
	*n = 0; return nullptr;
}

const IdxStr* HIN_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows(HIN_Speech);   return HIN_Speech;
		case OVL_ONSCREEN: *n = countRows(HIN_OnScreen); return HIN_OnScreen;
		case OVL_QUEST:    *n = countRows(HIN_Quest);    return HIN_Quest;
	}
	*n = 0; return nullptr;
}

