		case UM_4_ArchBishop_Lazarus: return "\xA9\xFA\xAD\xF0\xA9\xBE\xAC\xE8\xA8\xD4 \xAB\xC5\xA3\xDF\xAA\xEA\xAD\xCC";
		case UM_5_Red_Vex: return "\xAB\xC5\xAB\xC2 \xAC\xDC\xAE\xBD\xAD\xCC";
