		case TraitId::Negotiant: return "\xA7\xBA\xA1\xB4\xA8\xAE \xAA\xB2 \xA7\xB1\xAA\xB8 \xA8\xD4\xAA\xDE \xA1\xA1\xA6\xD0\xAA\xE4\xAE\xBD\xA6\xCA 10% \xA3\xCA\xA4\xE1, \xAC\xC7\xAD\xF2 \xA9\xCD\xAD\xED\xA6\xCA\xAA\xDE \xA9\xFD\xAB\xC2 \xAA\xA2\xAB\xC2\xA8\xA7 \xA1\xC6 \xA1\xA1\xAC\xC7\xAD\xCC\xAA\xDE";
